'use client';

import { useEffect } from 'react';
import dynamic from 'next/dynamic';
import { useScrollStore } from '@/stores/scrollStore';

const ClockScene = dynamic(() => import('@/components/three/ClockScene'), {
  ssr: false,
});

export default function ClockTestPage() {
  useEffect(() => {
    // Force clock phase: cycleProgress 0.52 => clockProgress ~0.25 (hold 6:59)
    useScrollStore.getState().setCycleProgress(0.52);
  }, []);

  return (
    <div style={{ width: '100vw', height: '100vh', background: '#0a0a08' }}>
      <ClockScene reducedMotion={false} />
    </div>
  );
}
